export const timelineModuleRef = { name: "@hypit/timeline", version: "1" };
export const timelineTypes = {
    timeline: { module: timelineModuleRef, name: "Timeline" },
    clock: { module: timelineModuleRef, name: "Clock" },
};
const string = { kind: "string", minLength: 1 };
const positiveInteger = { kind: "number", integer: true, minimum: 1 };
const object = (fields) => ({ kind: "object", fields });
export const clockSchema = object({
    frameRate: { schema: object({
            numerator: { schema: positiveInteger },
            denominator: { schema: positiveInteger },
        }) },
});
export const timelineSchema = object({
    id: { schema: string },
    ...(clockSchema.kind === "object" ? clockSchema.fields : {}),
    frameCount: { schema: positiveInteger },
});
export const timelineManifest = {
    format: "hypit.module@1",
    name: timelineModuleRef.name,
    version: timelineModuleRef.version,
    dependencies: [],
    types: [{ name: timelineTypes.timeline.name }, { name: timelineTypes.clock.name }],
    capabilities: [],
    producers: [],
};
export const timelineDependency = { module: timelineModuleRef };
